using AeroCompliance.ApiService.Authorization; using AeroCompliance.ApiService.Services; using AeroCompliance.Contracts.Dtos.Common; using AeroCompliance.Contracts.Dtos.Gis; using AeroCompliance.Domain.Entities; using AeroCompliance.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AeroCompliance.ApiService.Controllers;
[ApiController,Route("api/roads"),Authorize] public sealed class RoadsController(AeroComplianceDbContext db,ICurrentUserContext user,IAuditService audit):ControllerBase
{
 [HttpGet] public async Task<ActionResult<PagedResponse<RoadDto>>> List(int page=1,int pageSize=25,Guid? municipalityId=null,string? search=null,string? roadType=null,CancellationToken ct=default){if(!ApiSupport.IsValidPagination(page,pageSize))return Problem(statusCode:400,title:"Invalid pagination");var q=Visible().AsNoTracking();if(user.IsPlatformAdmin&&municipalityId.HasValue)q=q.Where(x=>x.MunicipalityId==municipalityId);var s=ApiSupport.NormalizeSearch(search);if(s is not null)q=q.Where(x=>x.RoadCode.ToLower().Contains(s)||(x.Name!=null&&x.Name.ToLower().Contains(s)));if(!string.IsNullOrWhiteSpace(roadType))q=q.Where(x=>x.RoadType==roadType.Trim());var total=await q.CountAsync(ct);var rows=await q.OrderBy(x=>x.RoadCode).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct);return Ok(new PagedResponse<RoadDto>(rows.Select(Map).ToList(),page,pageSize,total,total==0?0:(int)Math.Ceiling(total/(double)pageSize)));}
 [HttpGet("{id:guid}")] public async Task<ActionResult<RoadDto>> Get(Guid id,CancellationToken ct){var x=await Visible().AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct);return x is null?NotFound():Ok(Map(x));}
 [HttpPost,Authorize(Policy=Policies.ManageGis)] public async Task<ActionResult<RoadDto>> Create(SaveRoadRequest r,CancellationToken ct){if(!TryTenant(r.MunicipalityId,out var tenant))return Forbid();if(!await db.Municipalities.AnyAsync(x=>x.Id==tenant,ct))return NotFound();if(!GeoJsonService.TryReadMultiPolygon(r.Geometry,out var g,out var e))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:e);var code=r.RoadCode.Trim();if(await db.Roads.AnyAsync(x=>x.MunicipalityId==tenant&&x.RoadCode==code,ct))return Problem(statusCode:409,title:"Conflict",detail:"Road code already exists in this municipality.");var x=new Road{Id=Guid.NewGuid(),MunicipalityId=tenant,RoadCode=code,Name=r.Name?.Trim(),RoadType=r.RoadType?.Trim(),WidthM=r.WidthM,SpeedLimitKmh=r.SpeedLimitKmh,IsSensitive=r.IsSensitive,Geom=g,CreatedAt=DateTimeOffset.UtcNow};db.Roads.Add(x);audit.Add("road.create","Road",x.Id,after:new{x.MunicipalityId,x.RoadCode,x.Name,x.RoadType,x.WidthM,x.SpeedLimitKmh,x.IsSensitive},municipalityId:x.MunicipalityId);await db.SaveChangesAsync(ct);return CreatedAtAction(nameof(Get),new{id=x.Id},Map(x));}
 [HttpPut("{id:guid}"),Authorize(Policy=Policies.ManageGis)] public async Task<ActionResult<RoadDto>> Update(Guid id,SaveRoadRequest r,CancellationToken ct){var x=await Visible().SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();if(user.IsPlatformAdmin&&r.MunicipalityId.HasValue&&r.MunicipalityId!=x.MunicipalityId)return Problem(statusCode:409,title:"Conflict",detail:"A road cannot be moved between municipalities.");if(!GeoJsonService.TryReadMultiPolygon(r.Geometry,out var g,out var e))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:e);var code=r.RoadCode.Trim();if(await db.Roads.AnyAsync(y=>y.Id!=id&&y.MunicipalityId==x.MunicipalityId&&y.RoadCode==code,ct))return Problem(statusCode:409,title:"Conflict");var before=new{x.RoadCode,x.Name,x.RoadType,x.WidthM,x.SpeedLimitKmh,x.IsSensitive};x.RoadCode=code;x.Name=r.Name?.Trim();x.RoadType=r.RoadType?.Trim();x.WidthM=r.WidthM;x.SpeedLimitKmh=r.SpeedLimitKmh;x.IsSensitive=r.IsSensitive;x.Geom=g;audit.Add("road.update","Road",id,before,new{x.RoadCode,x.Name,x.RoadType,x.WidthM,x.SpeedLimitKmh,x.IsSensitive});await db.SaveChangesAsync(ct);return Ok(Map(x));}
 private IQueryable<Road> Visible()=>user.IsPlatformAdmin?db.Roads:db.Roads.Where(x=>x.MunicipalityId==user.MunicipalityId);private bool TryTenant(Guid? requested,out Guid tenant){if(user.IsPlatformAdmin){tenant=requested??Guid.Empty;return requested.HasValue;}tenant=user.MunicipalityId??Guid.Empty;return user.MunicipalityId.HasValue;}private static RoadDto Map(Road x)=>new(x.Id,x.MunicipalityId,x.RoadCode,x.Name,x.RoadType,x.WidthM,x.SpeedLimitKmh,x.IsSensitive,GeoJsonService.Write(x.Geom),x.CreatedAt);
}
